// Base64-embedded card-back artwork.
// Embedded (not loaded as separate files) so the JPG export's canvas
// never gets tainted by a cross-origin file load — this matters when
// index.html is opened directly via file:// instead of a local server.
const CARD_BACK_DATA_URLS = {
  normal: 'data:image/jpeg;base64,',
  gold: 'data:image/jpeg;base64,',
};
